CREATE TABLE IF NOT EXISTS products (
    id INT AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(255),
    category VARCHAR(100),
    brand VARCHAR(100),
    price FLOAT,
    rating FLOAT,
    image_url TEXT,
    description TEXT,
    tags VARCHAR(500),
    features TEXT,
    amazon_url TEXT,
    flipkart_url TEXT,
    myntra_url TEXT,
    price_range VARCHAR(20)
);

